// 2D DP：dp[i][j] = word1 前 i 字轉成 word2 前 j 字的最少操作數
// 時間複雜度: O(m·n)，空間複雜度: O(m·n)
function minDistance(word1, word2) {
    const m = word1.length, n = word2.length;
    const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
    for (let i = 0; i <= m; i++)
        dp[i][0] = i; // 全部刪除
    for (let j = 0; j <= n; j++)
        dp[0][j] = j; // 全部插入
    for (let i = 1; i <= m; i++) {
        for (let j = 1; j <= n; j++) {
            if (word1[i - 1] === word2[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1];
            }
            else {
                dp[i][j] = 1 + Math.min(dp[i - 1][j], // 刪除
                dp[i][j - 1], // 插入
                dp[i - 1][j - 1]);
            }
        }
    }
    return dp[m][n];
}

