class Solution {
    /**
     * 方法：動態規劃
     * 時間複雜度: O(m * n)
     * 空間複雜度: O(m * n)
     */
    public int minDistance(String word1, String word2) {
        int m = word1.length(), n = word2.length();

        int[][] dp = new int[m + 1][n + 1];

        // 初始化
        for (int i = 0; i <= m; i++) {
            dp[i][0] = i;
        }
        for (int j = 0; j <= n; j++) {
            dp[0][j] = j;
        }

        // 填充表格
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (word1.charAt(i-1) == word2.charAt(j-1)) {
                    dp[i][j] = dp[i-1][j-1];
                } else {
                    dp[i][j] = Math.min(
                        Math.min(dp[i][j-1], dp[i-1][j]),
                        dp[i-1][j-1]
                    ) + 1;
                }
            }
        }

        return dp[m][n];
    }

    /**
     * 空間優化版本
     * 時間複雜度: O(m * n)
     * 空間複雜度: O(n)
     */
    public int minDistance_optimized(String word1, String word2) {
        int m = word1.length(), n = word2.length();
        int[] dp = new int[n + 1];

        for (int j = 0; j <= n; j++) {
            dp[j] = j;
        }

        for (int i = 1; i <= m; i++) {
            int prev = dp[0];
            dp[0] = i;
            for (int j = 1; j <= n; j++) {
                int temp = dp[j];
                if (word1.charAt(i-1) == word2.charAt(j-1)) {
                    dp[j] = prev;
                } else {
                    dp[j] = Math.min(Math.min(dp[j-1], dp[j]), prev) + 1;
                }
                prev = temp;
            }
        }

        return dp[n];
    }
}

