// 1D DP（滾動陣列）：prev 保存左上角 dp[i-1][j-1]
// 時間複雜度: O(m·n)，空間複雜度: O(n)
static int min3(int a, int b, int c) {
    int m = a < b ? a : b;
    return m < c ? m : c;
}

int minDistance(char* word1, char* word2) {
    int m = strlen(word1), n = strlen(word2);
    int* dp = malloc(sizeof(int) * (n + 1));
    for (int j = 0; j <= n; j++) dp[j] = j;

    for (int i = 1; i <= m; i++) {
        int prev = dp[0];          // dp[i-1][0]
        dp[0] = i;
        for (int j = 1; j <= n; j++) {
            int tmp = dp[j];       // dp[i-1][j]，下一輪的左上角
            if (word1[i - 1] == word2[j - 1]) dp[j] = prev;
            else dp[j] = 1 + min3(dp[j], dp[j - 1], prev);
            prev = tmp;
        }
    }
    int ans = dp[n];
    free(dp);
    return ans;
}

